def tile_with_edges(S,Q):
    Hh,Ww=len(S),len(S[0]); RH,RW=len(Q),len(Q[0])
    out=[[0]*RW for _ in range(RH)]
    for r in range(RH):
        for c in range(RW):
            rr = (r) % Hh
            cc = (c) % Ww
            if S[rr][cc]==0:
                # try 4-neighbors first nonzero going up/left
                v=None
                for d in [(-1,0),(0,-1),(1,0),(0,1)]:
                    y,x=rr+d[0],cc+d[1]
                    if 0<=y<Hh and 0<=x<Ww and S[y][x]!=0: v=S[y][x]; break
                out[r][c]=v
            else: out[r][c]=S[rr][cc]
    return out
